78	class DispatcherNode : public rclcpp_lifecycle::LifecycleNode {
79	 public:
80	  explicit DispatcherNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions());
81	  ~DispatcherNode() override;
82	
83	  CallbackReturn on_configure(const rclcpp_lifecycle::State& state) override;
84	  CallbackReturn on_activate(const rclcpp_lifecycle::State& state) override;
85	  CallbackReturn on_deactivate(const rclcpp_lifecycle::State& state) override;
86	  CallbackReturn on_cleanup(const rclcpp_lifecycle::State& state) override;
87	  CallbackReturn on_shutdown(const rclcpp_lifecycle::State& state) override;
88	
89	 private:
90	  void SubmitOrderCb(
91	      const std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Request> req,
92	      std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Response> resp);
93	  void CancelOrderCb(
94	      const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Request> req,
95	      std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Response> resp);
96	  void PauseMissionCb(
97	      const std::shared_ptr<amr_dispatcher_interfaces::srv::PauseMission::Request> req,
98	      std::shared_ptr<amr_dispatcher_interfaces::srv::PauseMission::Response> resp);
99	  void ResumeMissionCb(
100	      const std::shared_ptr<amr_dispatcher_interfaces::srv::ResumeMission::Request> req,
101	      std::shared_ptr<amr_dispatcher_interfaces::srv::ResumeMission::Response> resp);
102	  void ReserveResourceCb(
103	      const std::shared_ptr<amr_dispatcher_interfaces::srv::ReserveResource::Request> req,
104	      std::shared_ptr<amr_dispatcher_interfaces::srv::ReserveResource::Response> resp);
105	  void ReleaseResourceCb(
106	      const std::shared_ptr<amr_dispatcher_interfaces::srv::ReleaseResource::Request> req,
107	      std::shared_ptr<amr_dispatcher_interfaces::srv::ReleaseResource::Response> resp);
108	
109	  // 12 Core Services
110	  void EnqueueMissionCb(
111	      const std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Request> req,
112	      std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Response> resp);
113	  void CancelQueuedMissionCb(
114	      const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Request> req,
115	      std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Response> resp);
116	  void PreemptMissionCb(
117	      const std::shared_ptr<amr_dispatcher_interfaces::srv::PreemptMission::Request> req,
118	      std::shared_ptr<amr_dispatcher_interfaces::srv::PreemptMission::Response> resp);
119	  void ReprioritizeQueuedMissionCb(
120	      const std::shared_ptr<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission::Request> req,
121	      std::shared_ptr<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission::Response> resp);
122	  void EstimateMissionCostCb(
123	      const std::shared_ptr<amr_dispatcher_interfaces::srv::EstimateMissionCost::Request> req,
