150	  using GoalHandleNavigate = rclcpp_action::ClientGoalHandle<NavigateSequence>;
151	
152	  rclcpp_action::GoalResponse HandleGoal(
153	      const rclcpp_action::GoalUUID& uuid,
154	      std::shared_ptr<const ExecuteMission::Goal> goal);
