159	  // ExecuteMission goal 终结方式：成功 succeed / 失败 abort / 取消 canceled
160	  enum class ExecuteFinish { kSucceed, kAbort, kCanceled };
161	  // 在 CompleteMission/FailMission/取消路径里查表终结 execute_goal_handles_ 中的 handle。
162	  // rclcpp_action 状态机约束：succeed/abort 仅 EXECUTING、canceled 仅 CANCELING，
163	  // 因此服务侧取消（未受理 action cancel）降级为 abort(error_code)。
164	  void FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
165	                         const std::string& message, std::int32_t error_code);
166	  // 服务侧/批量取消路径共用收口：终结 handle + 释放 HandleGoal 预占 +
167	  // 清 action 模式在途 NavigateSequence goal（CancelOrder/CancelQueued/整单批量复用）
168	  void CleanupMissionCancel(const std::string& mission_id, const std::string& reason);
169	  // 终态收口：遗忘任务的路由锁预留记账与派发起点
170	  //（Complete/Fail/取消/死锁取消/预占判负等路径共用，幂等）
171	  void ForgetMissionDispatchState(const std::string& mission_id);
172	  // 受理过的 action 取消（HandleCancel 返回 ACCEPT 后 goal 才进入 CANCELING）的延迟处理
173	  void ProcessActionCancels();
