175	  // NavigateSequence 客户端回调（navigation_backend=action 派发链）
176	  void NavGoalResponseCb(const std::string& mission_id, const GoalHandleNavigate::SharedPtr& goal_handle);
177	  void NavFeedbackCb(const std::string& mission_id, const GoalHandleNavigate::SharedPtr& goal_handle,
178	                     const std::shared_ptr<const NavigateSequence::Feedback> feedback);
179	  void NavResultCb(const std::string& mission_id, const GoalHandleNavigate::WrappedResult& result);
180	
181	  void ScheduleTick();
182	  void DeadlockTick();
183	  // 死锁快照组包（DeadlockTick 与 DetectTrafficDeadlockCb 共用，保证两处结论不分叉）：
184	  // 清点排队等待记录 + 活跃任务/进度 + 预约表 WFG 数据；不自带锁，调用方沿用各自约定
185	  amr_dispatcher_core::dispatcher::DeadlockSnapshot BuildDeadlockSnapshot();
186	  void PublishState();
187	  // 结果/取消/恢复后重新武装队列启动请求（行为树 runtime 门控的输入）
188	  void ReArmQueueStartRequest();
189	  void TrackingErrorCb(const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg);
190	  void OdomCb(const nav_msgs::msg::Odometry::SharedPtr msg);
191	  void CompleteMission(const std::string& mission_id, const std::string& reason);
192	  void FailMission(const std::string& mission_id, const std::string& reason);
193	
194	  std::unique_ptr<amr_dispatcher_core::dispatcher::MissionQueue> queue_;
195	  std::unique_ptr<amr_dispatcher_core::dispatcher::TrafficReservationTable> reservation_table_;
196	  std::unique_ptr<amr_dispatcher_core::dispatcher::MissionEventLog> event_log_;
197	  std::unique_ptr<amr_dispatcher_core::dispatcher::DeadlockDetector> deadlock_detector_;
198	  std::unique_ptr<amr_dispatcher_core::dispatcher::RecoveryPolicy> recovery_policy_;
199	  std::unique_ptr<amr_dispatcher_core::dispatcher::StationTopologyGraph> topology_graph_;
200	
201	  std::unordered_map<std::string, amr_dispatcher_core::dispatcher::Mission> active_missions_;
202	  std::unordered_map<std::string, std::size_t> mission_attempts_;
203	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_last_progress_;
204	  std::mutex active_missions_mutex_;
205	  std::uint64_t next_sequence_ = 1;
206	  bool deadlock_flag_ = false;
207	  // 最近一次 DeadlockTick 的环路径快照（findings[].cycle_path；无死锁时清空），
208	  // PublishState 据此投影 /dispatcher/topology_state 的死锁输入
209	  std::vector<std::vector<std::string>> last_deadlock_findings_;
210	  // 出队派发门控：由提单/入队置位，runtime 行为树消费（派发时清除）
211	  bool queue_start_requested_ = false;
212	  // 恢复策略回坞目标站点（由参数配置，缺失时回坞降级为仅事件记录）
213	  std::string recovery_dock_station_;
214	
215	  // 任务执行闭环：站点目录（mtime 热重载） + 规划器 + 最新里程计位姿
216	  std::unique_ptr<amr_dispatcher_core::IPathPlanner> planner_;
217	  std::unique_ptr<amr_dispatcher_core::catalog::StationCatalogReloader> catalog_reloader_;
218	  amr_dispatcher_core::path_tracking::Pose2D current_pose_{};
219	  bool has_odom_ = false;
220	  std::string tracking_mission_id_;  // 当前正在跟踪 /plan 的任务（单车一次一个）
221	
222	  rclcpp::Service<amr_dispatcher_interfaces::srv::SubmitOrder>::SharedPtr submit_srv_;
223	  rclcpp::Service<amr_dispatcher_interfaces::srv::CancelOrder>::SharedPtr cancel_srv_;
224	  rclcpp::Service<amr_dispatcher_interfaces::srv::PauseMission>::SharedPtr pause_srv_;
225	  rclcpp::Service<amr_dispatcher_interfaces::srv::ResumeMission>::SharedPtr resume_srv_;
226	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReserveResource>::SharedPtr reserve_srv_;
227	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReleaseResource>::SharedPtr release_srv_;
