231	  rclcpp_action::Client<NavigateSequence>::SharedPtr nav_client_;
232	  // mission_id -> 仍在执行的 ExecuteMission goal handle（终态时查表 finish 并移除）
233	  std::unordered_map<std::string, std::shared_ptr<GoalHandleExecute>> execute_goal_handles_;
234	  // mission_id -> 派发起点（PublishState 里按直线距离折算 percent_complete）
235	  std::unordered_map<std::string, amr_dispatcher_core::path_tracking::Pose2D> mission_dispatch_start_;
236	  // mission_id -> 派发时刻（ExecuteMission result.total_duration_sec 计算用，
237	  // 终态时在 FinishExecuteGoal/CompleteMission/FailMission/取消收口里遗忘）
238	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_dispatch_time_;
239	  // 导航后端：plan（默认，原 /plan 路径不变）| action（发 /navigate_sequence 单点 goal）
