17	DispatcherNode::DispatcherNode(const rclcpp::NodeOptions& options)
18	    : rclcpp_lifecycle::LifecycleNode("dispatcher_node", options) {
19	  declare_parameter("queue_capacity", 128);
20	  declare_parameter("comparator", "priority_fifo");
21	  declare_parameter("schedule_rate_hz", 10.0);
22	  declare_parameter("deadlock_check_rate_hz", 1.0);
23	  declare_parameter("max_active_missions", 4);
24	  declare_parameter("stations_file", "config/stations.yaml");
25	  declare_parameter("path_step_size_m", 0.1);
26	  declare_parameter("recovery_dock_station", "station_charge_1");
27	  declare_parameter("navigation_backend", "plan");
28	  recovery_dock_station_ = get_parameter("recovery_dock_station").as_string();
29	}
30	
31	DispatcherNode::~DispatcherNode() = default;
32	
33	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
34	  const std::size_t cap = get_parameter("queue_capacity").as_int();
35	  const std::string comp_name = get_parameter("comparator").as_string();
36	
37	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
38	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
39	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
40	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
41	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
42	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
43	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
44	          10s, 30s});
45	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
46	
47	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
48	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
49	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
50	  const std::string stations_file = get_parameter("stations_file").as_string();
51	  catalog_reloader_ =
52	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
53	  if (catalog_reloader_->loaded()) {
54	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
55	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
56	  } else {
57	    RCLCPP_WARN(get_logger(),
58	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
59	                stations_file.c_str());
60	  }
61	  planner_ = std::make_unique<amr_dispatcher_core::MockLinearPlanner>(
62	      get_parameter("path_step_size_m").as_double());
63	
64	  state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
65	      "/dispatcher/state", 10);
66	  event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
67	      "/dispatcher/events", 20);
68	  plan_pub_ = create_publisher<nav_msgs::msg::Path>("/plan", 1);
69	  // 拓扑状态：safety_gate（deadlock_active_）与 visualizer（绿锁边/红警戒柱）的死锁输入
70	  topology_pub_ = create_publisher<amr_dispatcher_interfaces::msg::TopologyState>(
71	      "/dispatcher/topology_state", 10);
72	
73	  // 位姿与到达信号订阅：path_tracker 的 TrackingError.arrived 驱动任务完成
74	  odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
75	      "/odom", 10, std::bind(&DispatcherNode::OdomCb, this, std::placeholders::_1));
76	  tracking_error_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
77	      "/tracking/error", 10,
78	      std::bind(&DispatcherNode::TrackingErrorCb, this, std::placeholders::_1));
79	
80	  submit_srv_ = create_service<amr_dispatcher_interfaces::srv::SubmitOrder>(
81	      "/dispatcher/submit_order",
82	      std::bind(&DispatcherNode::SubmitOrderCb, this, std::placeholders::_1, std::placeholders::_2));
83	  cancel_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelOrder>(
84	      "/dispatcher/cancel_order",
85	      std::bind(&DispatcherNode::CancelOrderCb, this, std::placeholders::_1, std::placeholders::_2));
86	  pause_srv_ = create_service<amr_dispatcher_interfaces::srv::PauseMission>(
87	      "/dispatcher/pause_mission",
88	      std::bind(&DispatcherNode::PauseMissionCb, this, std::placeholders::_1, std::placeholders::_2));
89	  resume_srv_ = create_service<amr_dispatcher_interfaces::srv::ResumeMission>(
90	      "/dispatcher/resume_mission",
91	      std::bind(&DispatcherNode::ResumeMissionCb, this, std::placeholders::_1, std::placeholders::_2));
92	  reserve_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveResource>(
93	      "/dispatcher/reserve_resource",
94	      std::bind(&DispatcherNode::ReserveResourceCb, this, std::placeholders::_1, std::placeholders::_2));
95	  release_srv_ = create_service<amr_dispatcher_interfaces::srv::ReleaseResource>(
96	      "/dispatcher/release_resource",
97	      std::bind(&DispatcherNode::ReleaseResourceCb, this, std::placeholders::_1, std::placeholders::_2));
98	
99	  // 12 Core Services Registration
100	  enqueue_srv_ = create_service<amr_dispatcher_interfaces::srv::EnqueueMission>(
101	      "/v2/enqueue_mission",
102	      std::bind(&DispatcherNode::EnqueueMissionCb, this, std::placeholders::_1, std::placeholders::_2));
103	  cancel_queued_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelQueuedMission>(
104	      "/v2/cancel_queued_mission",
105	      std::bind(&DispatcherNode::CancelQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
106	  preempt_srv_ = create_service<amr_dispatcher_interfaces::srv::PreemptMission>(
107	      "/v2/preempt_mission",
108	      std::bind(&DispatcherNode::PreemptMissionCb, this, std::placeholders::_1, std::placeholders::_2));
109	  reprioritize_srv_ = create_service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>(
110	      "/v2/reprioritize_queued_mission",
111	      std::bind(&DispatcherNode::ReprioritizeQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
112	  estimate_cost_srv_ = create_service<amr_dispatcher_interfaces::srv::EstimateMissionCost>(
113	      "/v2/estimate_mission_cost",
114	      std::bind(&DispatcherNode::EstimateMissionCostCb, this, std::placeholders::_1, std::placeholders::_2));
115	  block_route_srv_ = create_service<amr_dispatcher_interfaces::srv::BlockStationRoute>(
116	      "/v2/block_station_route",
117	      std::bind(&DispatcherNode::BlockStationRouteCb, this, std::placeholders::_1, std::placeholders::_2));
118	  detect_deadlock_srv_ = create_service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>(
119	      "/v2/detect_traffic_deadlock",
120	      std::bind(&DispatcherNode::DetectTrafficDeadlockCb, this, std::placeholders::_1, std::placeholders::_2));
121	  list_stations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListStations>(
122	      "/v2/list_stations",
123	      std::bind(&DispatcherNode::ListStationsCb, this, std::placeholders::_1, std::placeholders::_2));
124	  list_reservations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListTrafficReservations>(
125	      "/v2/list_traffic_reservations",
126	      std::bind(&DispatcherNode::ListTrafficReservationsCb, this, std::placeholders::_1, std::placeholders::_2));
127	  reserve_facility_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>(
128	      "/v2/reserve_facility_resource",
129	      std::bind(&DispatcherNode::ReserveFacilityResourceCb, this, std::placeholders::_1, std::placeholders::_2));
130	  snapshot_srv_ = create_service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>(
131	      "/v2/get_operator_snapshot",
132	      std::bind(&DispatcherNode::GetOperatorSnapshotCb, this, std::placeholders::_1, std::placeholders::_2));
133	  validate_site_srv_ = create_service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>(
134	      "/v2/validate_site_config",
135	      std::bind(&DispatcherNode::ValidateSiteConfigCb, this, std::placeholders::_1, std::placeholders::_2));
136	
137	  // 导航后端：默认 plan（行为与既有代码逐字节一致）；action 模式派发改发 NavigateSequence 单点 goal
138	  navigation_backend_ = get_parameter("navigation_backend").as_string();
139	  if (navigation_backend_ != "plan" && navigation_backend_ != "action") {
140	    RCLCPP_WARN(get_logger(), "Unknown navigation_backend '%s', falling back to 'plan'",
141	                navigation_backend_.c_str());
142	    navigation_backend_ = "plan";
143	  }
144	  // ExecuteMission action server：HandleGoal 校验（非空/不重复/资源可预占），
145	  // HandleAccepted 只做入队 + 存 goal handle（不起线程）
146	  execute_action_server_ = rclcpp_action::create_server<ExecuteMission>(
147	      this, "/execute_mission",
148	      std::bind(&DispatcherNode::HandleGoal, this, std::placeholders::_1, std::placeholders::_2),
149	      std::bind(&DispatcherNode::HandleCancel, this, std::placeholders::_1),
150	      std::bind(&DispatcherNode::HandleAccepted, this, std::placeholders::_1));
151	  if (navigation_backend_ == "action") {
152	    nav_client_ = rclcpp_action::create_client<NavigateSequence>(this, "/navigate_sequence");
153	  }
154	
155	  RCLCPP_INFO(get_logger(),
156	              "DispatcherNode configured (capacity=%zu, comparator=%s, navigation_backend=%s)",
157	              cap, comp_name.c_str(), navigation_backend_.c_str());
158	  return CallbackReturn::SUCCESS;
