161	CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*state*/) {
162	  state_pub_->on_activate();
163	  event_pub_->on_activate();
164	  plan_pub_->on_activate();
165	  topology_pub_->on_activate();
166	
167	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
168	  schedule_timer_ = create_wall_timer(
169	      std::chrono::duration<double>(1.0 / sched_hz),
170	      std::bind(&DispatcherNode::ScheduleTick, this));
171	
172	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
173	  deadlock_timer_ = create_wall_timer(
174	      std::chrono::duration<double>(1.0 / deadlock_hz),
175	      std::bind(&DispatcherNode::DeadlockTick, this));
176	
177	  state_timer_ = create_wall_timer(500ms, std::bind(&DispatcherNode::PublishState, this));
178	
179	  // 1Hz 驱动站点目录 mtime 热重载（HotReloadWatcher 由调用方驱动）
180	  reload_timer_ = create_wall_timer(1s, [this]() {
181	    if (!catalog_reloader_) return;
182	    if (catalog_reloader_->Tick()) {
183	      RCLCPP_INFO(get_logger(), "Station catalog hot-reloaded: %zu stations",
184	                  catalog_reloader_->catalog().stations.size());
185	    } else if (!catalog_reloader_->last_error().empty()) {
186	      // 重载失败（YAML 解析或校验不过）：旧目录继续生效，节流告警提示修复文件
187	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
188	                           "Station catalog reload failed, keeping previous: %s",
189	                           catalog_reloader_->last_error().c_str());
190	    }
191	  });
192	
193	  RCLCPP_INFO(get_logger(), "DispatcherNode activated");
194	  return CallbackReturn::SUCCESS;
195	}
