263	void DispatcherNode::SubmitOrderCb(
264	    const std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Request> req,
265	    std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Response> resp) {
266	  if (!queue_) {
267	    resp->accepted = false;
268	    resp->message = "Dispatcher not configured";
269	    return;
270	  }
271	
272	  // 订单路由：经 submit_order 行为树调用路由器，决定订单类型语义与字段回填。
273	  // 未知/空类型由路由器统一拒绝（message 带 supported 列表）。
274	  amr_dispatcher_bt::SubmitOrderBehaviorTreeInput route_input;
275	  route_input.request.order_id = req->order_id.empty() ? req->mission_id : req->order_id;
276	  route_input.request.order_type = req->mission_type.empty() ? "transport" : req->mission_type;
277	  route_input.request.priority = req->priority;
278	  const auto route_result = amr_dispatcher_bt::TickSubmitOrderBehaviorTree(route_input);
279	  if (!route_result.success || !route_result.route) {
280	    resp->accepted = false;
281	    resp->mission_id = req->mission_id;
282	    resp->message = "route rejected: " + route_result.message;
283	    RCLCPP_WARN(get_logger(), "SubmitOrder rejected by router: %s", resp->message.c_str());
284	    return;
285	  }
286	  const auto& route = *route_result.route;
287	
288	  amr_dispatcher_core::dispatcher::Mission m;
289	  m.id = req->mission_id.empty() ? ("m_" + std::to_string(next_sequence_)) : req->mission_id;
290	  m.order_id = req->order_id.empty() ? ("ord_" + m.id) : req->order_id;
291	  m.type = route.normalized_order_type.empty() ? "transport" : route.normalized_order_type;
292	  // 站点字段优先取请求显式值，路由器解析出的站点作兜底
293	  m.pickup_station = req->pickup_station.empty() ? route.pickup_station : req->pickup_station;
294	  m.dropoff_station = req->dropoff_station.empty() ? route.dropoff_station : req->dropoff_station;
295	  m.priority = req->priority;
296	  m.sequence = next_sequence_++;
297	  m.deadline_unix_ms = req->deadline_unix_ms;
298	  m.expected_seconds = req->expected_seconds;
299	
300	  auto res = queue_->Push(m);
301	  resp->accepted = res.accepted;
302	  resp->mission_id = m.id;
303	  resp->message = res.message;
304	
305	  if (res.accepted) {
306	    if (route.start_if_idle) {
307	      queue_start_requested_ = true;
308	    }
309	    RCLCPP_INFO(get_logger(),
310	                "SubmitOrder routed via BT: branch=%s kind=%d type=%s start_if_idle=%d",
311	                route_result.branch.c_str(), static_cast<int>(route.kind), m.type.c_str(),
312	                route.start_if_idle ? 1 : 0);
313	    amr_dispatcher_core::dispatcher::MissionEvent evt;
314	    evt.stamp = "now";
315	    evt.mission_id = m.id;
316	    evt.event = "queued";
317	    event_log_->Append(evt);
318	
319	    if (event_pub_ && event_pub_->is_activated()) {
320	      amr_dispatcher_interfaces::msg::MissionEvent msg;
321	      msg.stamp = now();
322	      msg.mission_id = m.id;
323	      msg.order_id = m.order_id;
324	      msg.event = "queued";
325	      msg.to_state = "PENDING";
326	      msg.reason = "submitted";
327	      event_pub_->publish(msg);
328	    }
329	  }
330	}
