332	void DispatcherNode::CancelOrderCb(
333	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Request> req,
334	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Response> resp) {
335	  if (!queue_) {
336	    resp->success = false;
337	    resp->message = "Dispatcher not active";
338	    return;
339	  }
340	  if (!req->mission_id.empty()) {
341	    bool ok = queue_->Cancel(req->mission_id);
342	    if (ok) {
343	      // action 提交的任务在排队中被取消：helper 终结 handle + 释放 HandleGoal 预占
344	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
345	      resp->success = true;
346	      resp->canceled_count = 1;
347	      resp->message = "Mission canceled from queue";
348	    } else {
349	      auto it = active_missions_.find(req->mission_id);
350	      if (it != active_missions_.end()) {
351	        // 释放资源锁；若该任务正在占用 /plan，发空路径停车
352	        if (reservation_table_) {
353	          reservation_table_->Release(req->mission_id);
354	        }
355	        if (tracking_mission_id_ == req->mission_id) {
356	          tracking_mission_id_.clear();
357	          if (plan_pub_ && plan_pub_->is_activated()) {
358	            nav_msgs::msg::Path empty;
359	            empty.header.stamp = now();
360	            empty.header.frame_id = "map";
361	            plan_pub_->publish(empty);
362	          }
363	        }
364	        active_missions_.erase(it);
365	        // helper：终结 ExecuteMission goal（未受理 action cancel → 降级 abort(3)）
366	        // 并级联取消在途 NavigateSequence goal（清 pending_nav_*）
367	        CleanupMissionCancel(req->mission_id, "mission canceled by operator");
368	        resp->success = true;
369	        resp->canceled_count = 1;
370	        resp->message = "Active mission canceled";
371	      } else {
372	        resp->success = false;
373	        resp->canceled_count = 0;
374	        resp->message = "Mission not found";
375	      }
376	    }
377	    ReArmQueueStartRequest();  // 取消活动任务后，队列后续任务需重新武装启动请求
378	    return;
379	  }
380	  if (!req->order_id.empty()) {
381	    // 整单批量取消：取消前对在队任务取证（仅存在 action handle 时取证，plan 模式零开销），
382	    // 取消成功后逐个收口 handle/预占/pending_nav（审查 I5）
383	    std::vector<std::string> action_mission_ids;
384	    if (!execute_goal_handles_.empty()) {
385	      for (const auto& qm : queue_->Snapshot()) {
386	        if (qm.order_id == req->order_id) {
387	          action_mission_ids.push_back(qm.id);
388	        }
389	      }
390	    }
391	    std::size_t count = queue_->CancelOrder(req->order_id);
392	    for (const auto& id : action_mission_ids) {
393	      CleanupMissionCancel(id, "mission canceled by operator");
394	    }
395	    resp->success = true;
396	    resp->canceled_count = static_cast<uint32_t>(count);
397	    resp->message = "Order canceled, count=" + std::to_string(count);
398	    ReArmQueueStartRequest();
399	    return;
400	  }
401	  resp->success = false;
402	  resp->message = "Neither mission_id nor order_id specified";
403	}
