617	void DispatcherNode::DetectTrafficDeadlockCb(
618	    const std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Request> /*req*/,
619	    std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Response> resp) {
620	  if (!deadlock_detector_) {
621	    resp->success = false;
622	    resp->deadlocked = false;
623	    resp->message = "Deadlock detector unconfigured";
624	    return;
625	  }
626	  // 快照组包与 DeadlockTick 共用 helper：服务入口与定时检测结论不分叉；
627	  // 沿用本回调既有的 active_missions_ 加锁约定（helper 自身不带锁）
628	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
629	  {
630	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
631	    snap = BuildDeadlockSnapshot();
632	  }
633	  const auto findings = deadlock_detector_->Detect(snap);
634	  resp->success = true;
635	  resp->deadlocked = !findings.empty();
636	  resp->message = resp->deadlocked ? "Deadlock detected in graph" : "No deadlock detected";
637	  for (const auto& f : findings) {
638	    for (const auto& mid : f.mission_ids) {
639	      resp->mission_ids.push_back(mid);
640	    }
641	    // cycle_path 为任务/资源交替闭合序列：奇数位才是资源 id（任务 id 不得混入）
642	    for (std::size_t i = 1; i < f.cycle_path.size(); i += 2) {
643	      resp->conflict_resource_ids.push_back(f.cycle_path[i]);
644	    }
645	    resp->descriptions.push_back(f.description);
646	  }
647	}
