720	rclcpp_action::GoalResponse DispatcherNode::HandleGoal(
721	    const rclcpp_action::GoalUUID& /*uuid*/,
722	    std::shared_ptr<const ExecuteMission::Goal> goal) {
723	  if (!goal || goal->mission_id.empty()) {
724	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: empty mission_id");
725	    return rclcpp_action::GoalResponse::REJECT;
726	  }
727	  if ((queue_ && queue_->Contains(goal->mission_id)) ||
728	      active_missions_.count(goal->mission_id) > 0) {
729	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: duplicate mission_id %s",
730	                goal->mission_id.c_str());
731	    return rclcpp_action::GoalResponse::REJECT;
732	  }
733	  // required_resources 可预占：Reserve 原子性（不落任何锁即失败），失败即 REJECT
734	  if (!goal->required_resources.empty()) {
735	    if (!reservation_table_) {
736	      RCLCPP_WARN(get_logger(),
737	                  "ExecuteMission goal rejected: reservation table unavailable for %s",
738	                  goal->mission_id.c_str());
739	      return rclcpp_action::GoalResponse::REJECT;
740	    }
741	    auto res = reservation_table_->Reserve(goal->mission_id, goal->required_resources);
742	    if (!res.success) {
743	      RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: reserve failed for %s: %s",
744	                  goal->mission_id.c_str(), res.message.c_str());
745	      return rclcpp_action::GoalResponse::REJECT;
746	    }
747	  }
748	  // DEFER + HandleAccepted 里显式 execute()：不受框架是否隐式 execute 影响的稳妥路径
749	  return rclcpp_action::GoalResponse::ACCEPT_AND_DEFER;
750	}
