752	rclcpp_action::CancelResponse DispatcherNode::HandleCancel(
753	    const std::shared_ptr<GoalHandleExecute> goal_handle) {
754	  if (execute_goal_handles_.find(goal_handle->get_goal()->mission_id) ==
755	      execute_goal_handles_.end()) {
756	    return rclcpp_action::CancelResponse::REJECT;
757	  }
758	  // 只受理取消请求：rclcpp_action 在本回调返回 ACCEPT 之后才把 goal 迁移到
759	  // CANCELING，而 canceled() 只允许在 CANCELING 态调用——
760	  // 实际的任务取消与 goal 终结延后到 ProcessActionCancels（ScheduleTick 内）。
761	  return rclcpp_action::CancelResponse::ACCEPT;
762	}
763	
764	void DispatcherNode::HandleAccepted(const std::shared_ptr<GoalHandleExecute> goal_handle) {
765	  const auto goal = goal_handle->get_goal();
766	  // ACCEPTED -> EXECUTING：后续 publish_feedback/succeed/abort 的前置条件
767	  goal_handle->execute();
768	
769	  if (!queue_) {
770	    if (reservation_table_) {
771	      reservation_table_->Release(goal->mission_id);
772	    }
773	    auto result = std::make_shared<ExecuteMission::Result>();
774	    result->success = false;
775	    result->error_code = 1;
776	    result->message = "dispatcher not configured";
777	    goal_handle->abort(result);
778	    return;
779	  }
780	
781	  amr_dispatcher_core::dispatcher::Mission m;
782	  m.id = goal->mission_id;
783	  m.order_id = goal->mission_id;  // 订单号=任务号，保证整单取消可寻址
784	  m.priority = goal->priority;
785	  m.dropoff_station = goal->target_station;
786	  if (goal->deadline_seconds > 0.0) {
787	    m.deadline_unix_ms =
788	        std::chrono::duration_cast<std::chrono::milliseconds>(
789	            std::chrono::system_clock::now().time_since_epoch())
790	            .count() +
791	        static_cast<std::int64_t>(goal->deadline_seconds * 1000.0);
792	  }
793	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
794	  m.sequence = next_sequence_++;
795	
796	  auto push = queue_->Push(m);
797	  if (!push.accepted) {
798	    // 入队失败回滚 HandleGoal 的资源预占并 abort（死锁风险下的显式失败出口）
799	    if (reservation_table_) {
800	      reservation_table_->Release(m.id);
801	    }
802	    auto result = std::make_shared<ExecuteMission::Result>();
803	    result->success = false;
804	    result->error_code = 1;
805	    result->message = "enqueue rejected: " + push.message;
806	    goal_handle->abort(result);
807	    RCLCPP_WARN(get_logger(), "ExecuteMission enqueue rejected for %s: %s", m.id.c_str(),
808	                push.message.c_str());
809	    return;
810	  }
811	
812	  execute_goal_handles_[m.id] = goal_handle;
813	  queue_start_requested_ = true;  // action 提交的任务武装 runtime 出队启动请求
814	  RCLCPP_INFO(get_logger(),
815	              "ExecuteMission accepted: %s -> queued (target=%s, prio=%d, resources=%zu)",
816	              m.id.c_str(), m.dropoff_station.c_str(), m.priority,
817	              goal->required_resources.size());
818	}
