820	void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
821	                                        const std::string& message, std::int32_t error_code) {
822	  auto it = execute_goal_handles_.find(mission_id);
823	  if (it == execute_goal_handles_.end()) {
824	    return;
825	  }
826	  auto handle = it->second;
827	  execute_goal_handles_.erase(it);
828	
829	  // total_duration_sec：按派发时刻计时（排队中取消等未派发场景为 0），
830	  // 计时后即遗忘时间戳，防止 map 长期驻留
831	  double duration_sec = 0.0;
832	  auto dispatch_time = mission_dispatch_time_.find(mission_id);
833	  if (dispatch_time != mission_dispatch_time_.end()) {
834	    duration_sec = std::chrono::duration<double>(
835	                       std::chrono::steady_clock::now() - dispatch_time->second)
836	                       .count();
837	    mission_dispatch_time_.erase(dispatch_time);
838	  }
839	  if (!handle || !handle->is_active()) {
840	    return;
841	  }
842	
843	  auto result = std::make_shared<ExecuteMission::Result>();
844	  result->success = (kind == ExecuteFinish::kSucceed);
845	  result->error_code = error_code;
846	  result->message = message;
847	  result->total_duration_sec = duration_sec;
848	  try {
849	    if (handle->is_canceling()) {
850	      // 已受理 action cancel：只能走 canceled()（rclcpp_action 状态机约束）
851	      handle->canceled(result);
852	    } else if (handle->is_executing()) {
853	      if (kind == ExecuteFinish::kSucceed) {
854	        handle->succeed(result);
855	      } else {
856	        // kAbort 与服务侧取消（未进入 CANCELING 无法 canceled()）降级为 abort
857	        handle->abort(result);
858	      }
859	    } else {
860	      // ACCEPTED 未执行的兜底：先 execute 再 abort，避免 rclcpp_action 状态断言
861	      handle->execute();
862	      handle->abort(result);
863	    }
864	    RCLCPP_INFO(get_logger(), "ExecuteMission goal finished: %s kind=%d (%s)",
865	                mission_id.c_str(), static_cast<int>(kind), message.c_str());
866	  } catch (const std::exception& ex) {
867	    RCLCPP_ERROR(get_logger(), "FinishExecuteGoal(%s) failed: %s", mission_id.c_str(), ex.what());
868	  }
869	}
