871	void DispatcherNode::CleanupMissionCancel(const std::string& mission_id,
872	                                          const std::string& reason) {
873	  // HandleGoal 预占的 required_resources 随任务取消一并释放（plan 模式无 handle 时
874	  // Release 对无锁持有者是无操作，与既有行为一致）
875	  const bool has_handle = execute_goal_handles_.count(mission_id) > 0;
876	  if (has_handle && reservation_table_) {
877	    reservation_table_->Release(mission_id);
878	  }
879	  // action 模式级联：取消在途 NavigateSequence goal 并清 pending 标记
880	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
881	    if (nav_client_ && pending_nav_goal_handle_) {
882	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
883	    }
884	    pending_nav_mission_id_.clear();
885	    pending_nav_goal_handle_.reset();
886	  }
887	  if (has_handle) {
888	    // 服务侧取消未受理 action cancel（handle 不在 CANCELING），降级 abort(3 PREEMPTED)
889	    // （total_duration_sec 的时间戳由 FinishExecuteGoal 计时后遗忘）
890	    FinishExecuteGoal(mission_id, ExecuteFinish::kCanceled, reason, 3);
891	  } else {
892	    mission_dispatch_time_.erase(mission_id);
893	  }
894	  ForgetMissionDispatchState(mission_id);
895	}
