897	void DispatcherNode::ForgetMissionDispatchState(const std::string& mission_id) {
898	  // 路由锁预留记账、排队等待记录与派发起点同步遗忘：
899	  // 幂等，供 Complete/Fail/取消/死锁取消/预占判负等终态路径共用
900	  mission_reserved_at_.erase(mission_id);
901	  pending_wait_.erase(mission_id);
902	  mission_dispatch_start_.erase(mission_id);
903	}
904	
905	void DispatcherNode::ProcessActionCancels() {
906	  if (execute_goal_handles_.empty()) {
907	    return;
908	  }
909	  std::vector<std::string> canceling;
910	  canceling.reserve(execute_goal_handles_.size());
911	  for (const auto& [id, handle] : execute_goal_handles_) {
912	    if (handle && handle->is_canceling()) {
913	      canceling.push_back(id);
914	    }
915	  }
916	  for (const auto& id : canceling) {
917	    RCLCPP_INFO(get_logger(), "ExecuteMission cancel accepted by action client: %s", id.c_str());
918	    bool canceled = false;
919	    if (queue_ && queue_->Cancel(id)) {
920	      // 排队中任务被 action 取消：连带释放 HandleGoal 预占的 required_resources
921	      if (reservation_table_) {
922	        reservation_table_->Release(id);
923	      }
924	      canceled = true;
925	    } else {
926	      auto it = active_missions_.find(id);
927	      if (it != active_missions_.end()) {
928	        if (reservation_table_) {
929	          reservation_table_->Release(id);
930	        }
931	        if (tracking_mission_id_ == id) {
932	          tracking_mission_id_.clear();
933	          if (plan_pub_ && plan_pub_->is_activated()) {
934	            nav_msgs::msg::Path empty;
935	            empty.header.stamp = now();
936	            empty.header.frame_id = "map";
937	            plan_pub_->publish(empty);
938	          }
939	        }
940	        active_missions_.erase(it);
941	        canceled = true;
942	      }
943	    }
944	    ForgetMissionDispatchState(id);  // 取消终态：路由锁记账/等待记录/派发起点遗忘
945	    // action 模式级联：取消在途的 NavigateSequence goal 并清 pending 标记
946	    if (navigation_backend_ == "action" && pending_nav_mission_id_ == id) {
947	      if (nav_client_ && pending_nav_goal_handle_) {
948	        nav_client_->async_cancel_goal(pending_nav_goal_handle_);
949	      }
950	      pending_nav_mission_id_.clear();
951	      pending_nav_goal_handle_.reset();
952	    }
953	    // 此时 handle 已确认 is_canceling()，canceled() 状态合法
954	    FinishExecuteGoal(id, ExecuteFinish::kCanceled, "mission canceled by action client", 3);
955	    if (canceled) {
956	      ReArmQueueStartRequest();
957	    }
958	  }
959	}
