961	void DispatcherNode::NavGoalResponseCb(const std::string& mission_id,
962	                                       const GoalHandleNavigate::SharedPtr& goal_handle) {
963	  if (!goal_handle) {
964	    RCLCPP_WARN(get_logger(), "NavigateSequence goal rejected by bridge for mission %s",
965	                mission_id.c_str());
966	    if (pending_nav_mission_id_ == mission_id) {
967	      pending_nav_mission_id_.clear();
968	      pending_nav_goal_handle_.reset();
969	    }
970	    // FailMission 内部会清理 tracking 槽位与空路径停车
971	    FailMission(mission_id, "navigate_sequence goal rejected by bridge");
972	    return;
973	  }
974	  // goal 响应到达时任务可能已被取消/完结：孤儿 goal 直接取消，
975	  // 否则 bridge 盲跑 + pending 句柄残留（审查 I4）
976	  bool mission_alive;
977	  {
978	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
979	    mission_alive = active_missions_.count(mission_id) > 0;
980	  }
981	  if (!mission_alive) {
982	    RCLCPP_WARN(get_logger(),
983	                "Stale NavigateSequence goal response for %s (mission gone); canceling orphan goal",
984	                mission_id.c_str());
985	    nav_client_->async_cancel_goal(goal_handle);
986	    if (pending_nav_mission_id_ == mission_id) {
987	      pending_nav_mission_id_.clear();
988	      pending_nav_goal_handle_.reset();
989	    }
990	    return;
991	  }
992	  pending_nav_goal_handle_ = goal_handle;
993	}
