995	void DispatcherNode::NavFeedbackCb(
996	    const std::string& mission_id, const GoalHandleNavigate::SharedPtr& /*goal_handle*/,
997	    const std::shared_ptr<const NavigateSequence::Feedback> feedback) {
998	  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();  // 喂死锁 idle 启发式
999	  if (!feedback) {
1000	    return;
1001	  }
1002	  // NavigateSequence feedback -> ExecuteMission feedback 映射
1003	  // （current_index/total -> state_code=2 EXECUTING + percent=index/total*100）
1004	  auto hit = execute_goal_handles_.find(mission_id);
1005	  if (hit == execute_goal_handles_.end() || !hit->second || !hit->second->is_executing()) {
1006	    return;
1007	  }
1008	  auto fb = std::make_shared<ExecuteMission::Feedback>();
1009	  fb->state_code = 2;  // EXECUTING
1010	  fb->current_node = feedback->current_station;
1011	  fb->percent_complete =
1012	      feedback->total_waypoints > 0
1013	          ? static_cast<float>(100.0 * static_cast<double>(feedback->current_index) /
1014	                               static_cast<double>(feedback->total_waypoints))
1015	          : 0.0f;
1016	  fb->estimated_remaining_sec = 0.0;
1017	  hit->second->publish_feedback(fb);
1018	}
