1020	void DispatcherNode::NavResultCb(const std::string& mission_id,
1021	                                 const GoalHandleNavigate::WrappedResult& result) {
1022	  if (pending_nav_mission_id_ == mission_id) {
1023	    pending_nav_mission_id_.clear();
1024	    pending_nav_goal_handle_.reset();
1025	  }
1026	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
1027	      result.result->success) {
1028	    CompleteMission(mission_id, "navigate_sequence succeeded");
1029	    return;
1030	  }
1031	  std::string msg;
1032	  if (result.result && !result.result->message.empty()) {
1033	    msg = result.result->message;
1034	  } else if (result.code == rclcpp_action::ResultCode::CANCELED) {
1035	    msg = "navigate_sequence canceled";
1036	  } else if (result.code == rclcpp_action::ResultCode::ABORTED) {
1037	    msg = "navigate_sequence aborted";
1038	  } else {
1039	    msg = "navigate_sequence failed";
1040	  }
1041	  FailMission(mission_id, msg);
1042	}
