1044	void DispatcherNode::ScheduleTick() {
1045	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1046	  ProcessActionCancels();
1047	  if (!queue_ || queue_->empty()) {
1048	    return;
1049	  }
1050	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1051	  if (active_missions_.size() >= max_active) {
1052	    return;
1053	  }
1054	
