1454	  std::string recovery_message;
1455	  if (handle_failure && queue_) {
1456	    amr_dispatcher_bt::MissionRecoveryBehaviorTreeInput rec_input;
1457	    rec_input.retry_count = mission_attempts_[mission_id];
1458	    rec_input.is_dock_mission = mission_copy.type == "charge";
1459	    rec_input.mission_id = mission_id;
1460	    rec_input.failure_message =
1461	        (result_bt.success && !result_bt.decision.failure_message.empty())
1462	            ? result_bt.decision.failure_message
1463	            : reason;
1464	    rec_input.recovery_priority = mission_copy.priority;
1465	    rec_input.next_queue_sequence = next_sequence_;
1466	    const auto rec_bt = amr_dispatcher_bt::TickMissionRecoveryBehaviorTree(rec_input);
1467	    recovery_action = rec_bt.decision.action;
1468	    recovery_message = rec_bt.decision.message;
1469	    RCLCPP_INFO(get_logger(), "Recovery via BT: branch=%s action=%s recoverable=%d (%s)",
1470	                rec_bt.branch.c_str(), rec_bt.decision.action.c_str(),
1471	                rec_bt.decision.recoverable ? 1 : 0, rec_bt.decision.message.c_str());
1472	
1473	    if (rec_bt.success && rec_bt.decision.action == "retry") {
1474	      auto retry = mission_copy;
1475	      retry.attempt += 1;
1476	      auto push = queue_->Push(retry);
1477	      if (push.accepted) {
1478	        mission_attempts_[mission_id] = rec_input.retry_count + 1;
1479	        queue_start_requested_ = true;
1480	      } else {
1481	        recovery_action = "manual";
1482	        recovery_message = "retry re-enqueue rejected: " + push.message;
1483	      }
1484	    } else if (rec_bt.success && rec_bt.decision.action == "dock") {
1485	      // 回坞：入队一条到充电站点的 charge 任务；站点缺失则降级为仅记录
1486	      const auto& catalog = catalog_reloader_ ? catalog_reloader_->catalog()
1487	                                              : amr_dispatcher_core::catalog::StationCatalog{};
1488	      const auto* dock_st = amr_dispatcher_core::catalog::FindStation(catalog, recovery_dock_station_);
1489	      if (dock_st) {
1490	        amr_dispatcher_core::dispatcher::Mission dock_m;
1491	        dock_m.id = "m_" + std::to_string(next_sequence_++);
1492	        dock_m.order_id = "dock_" + mission_id;
1493	        dock_m.type = "charge";
1494	        dock_m.dropoff_station = recovery_dock_station_;
1495	        dock_m.priority = mission_copy.priority;
1496	        dock_m.sequence = next_sequence_;
1497	        auto push = queue_->Push(dock_m);
1498	        if (push.accepted) {
1499	          queue_start_requested_ = true;
1500	        } else {
1501	          recovery_action = "manual";
1502	          recovery_message = "dock enqueue rejected: " + push.message;
1503	        }
1504	      } else {
1505	        recovery_action = "manual";
1506	        recovery_message = "dock station not found: " + recovery_dock_station_;
1507	      }
1508	    }
1509	
1510	    if (event_pub_ && event_pub_->is_activated()) {
1511	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1512	      msg.stamp = now();
1513	      msg.mission_id = mission_id;
1514	      msg.order_id = order_id;
1515	      msg.event = "recovery";
1516	      msg.from_state = "FAILED";
1517	      msg.to_state = recovery_action == "manual" ? "MANUAL_INTERVENTION" : "RECOVERING";
1518	      msg.reason = recovery_action + ": " + recovery_message;
1519	      event_pub_->publish(msg);
1520	    }
1521	    if (event_log_) {
1522	      amr_dispatcher_core::dispatcher::MissionEvent evt;
1523	      evt.stamp = "now";
1524	      evt.mission_id = mission_id;
1525	      evt.event = "recovery";
1526	      evt.message = recovery_action + ": " + recovery_message;
1527	      event_log_->Append(evt);
1528	    }
1529	  }
1530	  ReArmQueueStartRequest();
1531	}
1532	
1533	amr_dispatcher_core::dispatcher::DeadlockSnapshot DispatcherNode::BuildDeadlockSnapshot() {
1534	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
1535	  // 等待记录只对仍在排队的任务有效：被批量取消/离场的等待者不进 waiting_for
1536	  //（防 WFG 残留幽灵等待者；派发成功/终态路径已即时遗忘，此处兜底清扫）
1537	  if (queue_) {
1538	    for (auto wait = pending_wait_.begin(); wait != pending_wait_.end();) {
1539	      if (queue_->Contains(wait->first)) {
1540	        ++wait;
1541	      } else {
1542	        wait = pending_wait_.erase(wait);
1543	      }
1544	    }
1545	  }
1546	  for (const auto& [id, m] : active_missions_) {
1547	    snap.active_missions.push_back(m);
1548	    snap.last_progress[id] = mission_last_progress_[id];
1549	  }
1550	  // WFG 数据上环：held_by 与预留资源集合来自预约表快照（resource -> owner），
1551	  // waiting_for 来自 Peek 预留失败的排队任务，长持锁取证时刻来自任务预留记账
1552	  //（人工 ReserveResourceCb 不记，避免长持锁误报）
1553	  if (reservation_table_) {
1554	    for (const auto& [resource_id, owner_id] : reservation_table_->Snapshot()) {
1555	      snap.allocation_graph.held_by[resource_id] = owner_id;
1556	      snap.reserved_resource_ids.insert(resource_id);
1557	    }
1558	  }
1559	  snap.allocation_graph.waiting_for = pending_wait_;
1560	  snap.reservation_acquired_at = mission_reserved_at_;
1561	  return snap;
1562	}
1563	
1564	void DispatcherNode::DeadlockTick() {
1565	  if (!deadlock_detector_ || !recovery_policy_) {
1566	    return;
1567	  }
1568	
1569	  const auto snap = BuildDeadlockSnapshot();
1570	
1571	  const auto findings = deadlock_detector_->Detect(snap);
1572	  deadlock_flag_ = !findings.empty();
1573	
1574	  // 拓扑状态投影的死锁输入：存各 finding 的环路径，无死锁时清空
1575	  last_deadlock_findings_.clear();
1576	  for (const auto& finding : findings) {
1577	    if (!finding.cycle_path.empty()) {
1578	      last_deadlock_findings_.push_back(finding.cycle_path);
1579	    }
1580	  }
1581	
1582	  if (deadlock_flag_) {
1583	    RCLCPP_WARN(get_logger(), "Deadlock findings count: %zu", findings.size());
1584	    auto actions = recovery_policy_->Decide(
1585	        findings, [this](const std::string& mid) {
1586	          auto it = mission_attempts_.find(mid);
1587	          return it != mission_attempts_.end() ? it->second : 0;
1588	        });
1589	
1590	    for (const auto& act : actions) {
1591	      RCLCPP_WARN(get_logger(), "Recovery action on %s: reason=%s",
1592	                  act.mission_id.c_str(), act.reason.c_str());
1593	      if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kPause) {
1594	        queue_->PauseOrder(act.mission_id);
1595	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kCancel) {
1596	        // 取消也走结果树：canceled 分支给资源释放决策，同时补发可观测事件
1597	        std::string canceled_order_id;
1598	        auto cancel_it = active_missions_.find(act.mission_id);
1599	        if (cancel_it != active_missions_.end()) {
1600	          canceled_order_id = cancel_it->second.order_id;
1601	        }
1602	        amr_dispatcher_core::workflow::MissionResultWorkflowInput cancel_input;
1603	        cancel_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kCanceled;
1604	        cancel_input.result_message = act.reason;
1605	        const auto cancel_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(cancel_input);
1606	        active_missions_.erase(act.mission_id);
1607	        if (!cancel_bt.success || cancel_bt.decision.release_all_resources) {
1608	          if (reservation_table_) {
1609	            reservation_table_->Release(act.mission_id);
1610	          }
1611	        }
1612	        // 死锁恢复取消的级联：清在途 NavigateSequence goal + 终结 ExecuteMission goal
1613	        if (navigation_backend_ == "action" && pending_nav_mission_id_ == act.mission_id) {
1614	          if (nav_client_ && pending_nav_goal_handle_) {
1615	            nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1616	          }
1617	          pending_nav_mission_id_.clear();
1618	          pending_nav_goal_handle_.reset();
1619	        }
1620	        FinishExecuteGoal(act.mission_id, ExecuteFinish::kAbort, act.reason, 1);
1621	        mission_dispatch_time_.erase(act.mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1622	        ForgetMissionDispatchState(act.mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1623	        // 死锁恢复取消到正在跟踪 /plan 的任务时，必须释放跟踪槽位并停车，
1624	        // 否则 tracking_mission_id_ 悬挂导致后续任务永远无法下发。
1625	        if (tracking_mission_id_ == act.mission_id) {
1626	          tracking_mission_id_.clear();
1627	          if (plan_pub_ && plan_pub_->is_activated()) {
1628	            nav_msgs::msg::Path empty;
1629	            empty.header.stamp = now();
1630	            empty.header.frame_id = "map";
1631	            plan_pub_->publish(empty);
1632	          }
1633	        }
1634	        if (event_pub_ && event_pub_->is_activated()) {
1635	          amr_dispatcher_interfaces::msg::MissionEvent msg;
1636	          msg.stamp = now();
1637	          msg.mission_id = act.mission_id;
1638	          msg.order_id = canceled_order_id;
1639	          msg.event = "canceled";
1640	          msg.to_state = "CANCELED";
1641	          msg.reason = act.reason;
1642	          event_pub_->publish(msg);
1643	        }
1644	        RCLCPP_WARN(get_logger(), "Deadlock cancel via BT: branch=%s state=%s reason=%s",
1645	                    cancel_bt.branch.c_str(),
1646	                    cancel_bt.success ? cancel_bt.decision.state.c_str() : "tree_failed",
1647	                    act.reason.c_str());
1648	        ReArmQueueStartRequest();
1649	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kRetry) {
1650	        mission_attempts_[act.mission_id]++;
1651	        mission_last_progress_[act.mission_id] = std::chrono::steady_clock::now();
1652	      }
1653	    }
1654	  }
1655	}
1656	
1657	void DispatcherNode::ReArmQueueStartRequest() {
1658	  // 结果/取消/恢复后重新武装 runtime 行为树的启动请求：
1659	  // 队列非空则置位（auto_start_queue 语义），队列清空则复位。
1660	  const auto decision = amr_dispatcher_core::workflow::PlanMissionPostResultQueue(
1661	      amr_dispatcher_core::workflow::MissionPostResultQueueRequest{
1662	          /*existing_queue_start_requested=*/queue_start_requested_,
1663	          /*auto_start_queue=*/true,
1664	          /*queue_running=*/true,
1665	          /*mission_queue_empty=*/queue_ == nullptr || queue_->empty()});
1666	  queue_start_requested_ = decision.queue_start_requested;
1667	}
1668	
1669	void DispatcherNode::PublishState() {
1670	  if (!state_pub_ || !state_pub_->is_activated()) {
1671	    return;
1672	  }
1673	
1674	  amr_dispatcher_interfaces::msg::DispatcherState msg;
1675	  msg.header.stamp = now();
1676	  msg.current_comparator = queue_ ? queue_->comparator_name() : "none";
1677	  msg.queue_size = queue_ ? static_cast<uint32_t>(queue_->size()) : 0;
1678	  msg.queue_capacity = queue_ ? static_cast<uint32_t>(queue_->capacity()) : 0;
1679	  msg.active_missions_count = static_cast<uint32_t>(active_missions_.size());
1680	  msg.deadlock_detected = deadlock_flag_;
1681	
1682	  for (const auto& [id, _] : active_missions_) {
1683	    msg.active_mission_ids.push_back(id);
1684	  }
1685	  if (!msg.active_mission_ids.empty()) {
1686	    msg.active_mission_id = msg.active_mission_ids.front();
1687	  }
1688	
1689	  // ExecuteMission 进度反馈：按派发起点的直线距离折算 percent_complete
1690	  //（state_code=1 WAITING_LOCK 为计划定死的周期反馈语义；导航中的高频反馈由 NavFeedbackCb 发 state_code=2）
1691	  for (const auto& [id, handle] : execute_goal_handles_) {
1692	    if (!handle || !handle->is_executing()) {
1693	      continue;
1694	    }
1695	    auto ait = active_missions_.find(id);
1696	    if (ait == active_missions_.end()) {
1697	      continue;  // 任务已终态（finish 时会查表移除 handle）
1698	    }
1699	    double percent = 0.0;
1700	    auto sit = mission_dispatch_start_.find(id);
1701	    const bool catalog_loaded = catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1702	    if (sit != mission_dispatch_start_.end() && has_odom_ && catalog_loaded &&
1703	        !ait->second.dropoff_station.empty()) {
1704	      const auto* to_st = amr_dispatcher_core::catalog::FindStation(
1705	          catalog_reloader_->catalog(), ait->second.dropoff_station);
1706	      if (to_st) {
1707	        const double total = std::hypot(to_st->x - sit->second.x, to_st->y - sit->second.y);
1708	        const double covered =
1709	            std::hypot(current_pose_.x - sit->second.x, current_pose_.y - sit->second.y);
1710	        if (total > 1e-6) {
1711	          percent = std::min(100.0, 100.0 * covered / total);
1712	        }
1713	      }
1714	    }
1715	    auto fb = std::make_shared<ExecuteMission::Feedback>();
1716	    fb->state_code = 1;  // WAITING_LOCK（计划定死的周期反馈状态）
1717	    fb->current_node = ait->second.dropoff_station;
1718	    fb->percent_complete = static_cast<float>(percent);
1719	    fb->estimated_remaining_sec = 0.0;
1720	    handle->publish_feedback(fb);
1721	  }
1722	
1723	  state_pub_->publish(msg);
1724	
1725	  // /dispatcher/topology_state：safety_gate 与 visualizer 的死锁/锁边输入
1726	  //（快照全量透传，active 仅任务持有的 route_edge，deadlocked_nodes 解析成站点 id）
1727	  if (topology_pub_ && topology_pub_->is_activated()) {
1728	    std::unordered_set<std::string> active_ids;
1729	    for (const auto& [id, _] : active_missions_) {
1730	      active_ids.insert(id);
1731	    }
1732	    const std::vector<std::pair<std::string, std::string>> snapshot =
1733	        reservation_table_ ? reservation_table_->Snapshot()
1734	                           : std::vector<std::pair<std::string, std::string>>{};
1735	    const auto topology = amr_dispatcher_core::dispatcher::BuildTopologyProjection(
1736	        snapshot, active_ids, last_deadlock_findings_);
1737	    amr_dispatcher_interfaces::msg::TopologyState topology_msg;
1738	    topology_msg.stamp = now();
1739	    topology_msg.active_edges = topology.active_edges;
1740	    topology_msg.locked_edges = topology.locked_edges;
1741	    topology_msg.edge_owners = topology.edge_owners;
1742	    topology_msg.deadlocked_nodes = topology.deadlocked_nodes;
1743	    topology_msg.deadlock_detected = topology.deadlock_detected;
1744	    topology_pub_->publish(topology_msg);
1745	  }
1746	}
1747	
1748	}  // namespace amr_dispatcher_ros
1749	
1750	int main(int argc, char* argv[]) {
1751	  rclcpp::init(argc, argv);
1752	  auto node = std::make_shared<amr_dispatcher_ros::DispatcherNode>();
1753	  rclcpp::spin(node->get_node_base_interface());
1754	  rclcpp::shutdown();
1755	  return 0;
1756	}
