179	  // 联动 Fault Supervisor 降级限速规则
180	  if (fault_supervisor_->recommendation() == amr_dispatcher_core::safety::SystemActionRecommendation::kClampSpeed) {
181	    cmd.linear_x_mps = std::clamp(cmd.linear_x_mps, -0.2, 0.2);
182	  }
183	
184	  auto decision = gate_->Evaluate(cmd);
185	  last_decision_ = decision;
186	
187	  geometry_msgs::msg::Twist safe_cmd;
188	  safe_cmd.linear.x = decision.linear_x_mps;
189	  safe_cmd.linear.y = decision.linear_y_mps;
190	  safe_cmd.angular.z = decision.angular_z_radps;
