196	void SafetyGateNode::PublishIdleSafetyState() {
197	  // 无任何运动指令时构造零速裁决：allowed 由多源健康聚合决定，
198	  // reason 标注 idle 以便运维区分"门控放行"与"门控阻断"。
199	  amr_dispatcher_core::safety::CmdVelGateDecision idle;
200	  const bool effective_estop = estop_active_ || auto_fault_latched_;
201	  idle.allowed = watchdog_ok_ && !effective_estop && !bumper_active_ && !manual_takeover_active_;
202	  idle.reason = idle.allowed ? "idle" : "idle_blocked";
203	  idle.severity = effective_estop || bumper_active_ ? amr_dispatcher_core::safety::SafetySeverity::kCritical
204	                                                 : (watchdog_ok_ ? amr_dispatcher_core::safety::SafetySeverity::kInfo
205	                                                                 : amr_dispatcher_core::safety::SafetySeverity::kWarn);
206	  PublishSafetyState(idle);
207	}
