209	void SafetyGateNode::PublishSafetyState(const amr_dispatcher_core::safety::CmdVelGateDecision& decision) {
210	  amr_dispatcher_interfaces::msg::SafetyState state_msg;
211	  state_msg.header.stamp = now();
212	  state_msg.motion_allowed = decision.allowed;
213	  state_msg.reason = decision.reason;
214	
215	  if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical) {
216	    state_msg.severity = "CRITICAL";
217	    state_msg.speed_scale = 0.0;
218	  } else if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kWarn) {
219	    state_msg.severity = "WARN";
220	    state_msg.speed_scale = 0.3;
221	  } else {
222	    state_msg.severity = "INFO";
223	    state_msg.speed_scale = 1.0;
224	  }
225	
226	  if (estop_active_ || auto_fault_latched_) state_msg.active_sources.push_back("estop");
227	  if (bumper_active_) state_msg.active_sources.push_back("bumper");
228	  if (manual_takeover_active_) state_msg.active_sources.push_back("manual_takeover");
229	  if (!state_msg.active_sources.empty()) {
230	    state_msg.active_stop_source = state_msg.active_sources.front();
231	  }
232	
233	  safety_state_pub_->publish(state_msg);
234	}
