41	      "/cmd_vel_safe", 10,
42	      std::bind(&ChassisDriverNode::CmdVelCallback, this, std::placeholders::_1));
43	
44	  odom_pub_ = create_publisher<nav_msgs::msg::Odometry>("/odom", 20);
45	  health_pub_ = create_publisher<amr_dispatcher_interfaces::msg::ChassisLinkHealth>(
46	      "/chassis/link_health", 10);
