64	ChassisDriverNode::~ChassisDriverNode() = default;
65	
66	void ChassisDriverNode::CmdVelCallback(const geometry_msgs::msg::Twist::SharedPtr msg) {
67	  if (!backend_ctrl_ || !backend_ctrl_->current() || !backend_ctrl_->current()->IsOpen()) {
68	    return;
69	  }
70	  amr_dispatcher_core::chassis::ChassisCommand cmd;
71	  cmd.linear_x_mps = msg->linear.x;
72	  cmd.linear_y_mps = msg->linear.y;
73	  cmd.angular_z_radps = msg->angular.z;
74	
75	  std::string err;
76	  const auto t0 = std::chrono::steady_clock::now();
77	  if (!backend_ctrl_->current()->WriteCommand(cmd, &err)) {
78	    backend_ctrl_->RecordLoss();
79	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000, "WriteCommand failed: %s", err.c_str());
80	  } else {
81	    const auto dt_ms = std::chrono::duration<double, std::milli>(
82	        std::chrono::steady_clock::now() - t0).count();
83	    backend_ctrl_->RecordSuccess(dt_ms);
84	  }
85	}
86	
87	void ChassisDriverNode::ReadPollLoop() {
88	  if (!backend_ctrl_) return;
89	  if (!backend_ctrl_->current() || !backend_ctrl_->current()->IsOpen()) {
90	    // 连接已断（切档 Open 失败或后端关闭）：仍需驱动控制器，
91	    // 否则 LinkRecoveryPolicy 的退避重连永远不会被推进。
92	    std::string reason;
93	    if (backend_ctrl_->EvaluateAndMaybeSwitch(&reason)) {
94	      RCLCPP_WARN(get_logger(), "Chassis backend reconnected: %s", reason.c_str());
95	    }
96	    return;
97	  }
98	  std::string err;
99	  auto data = backend_ctrl_->current()->Read(&err);
100	  if (!data || data->empty()) {
101	    // 读路径失败计入丢帧：链路不活跃，链路质量滑窗需要感知
102	    if (!err.empty()) {
103	      backend_ctrl_->RecordLoss();
104	    }
105	    return;
106	  }
107	  text_stream_.Append(*data);
108	  const auto packets = text_stream_.DrainPackets();
109	  const auto now = this->now();
110	
111	  // 解析失败行计入丢帧
112	  const auto invalid_lines = text_stream_.InvalidLineCount();
113	  for (std::size_t i = 0; i < invalid_lines; ++i) {
114	    backend_ctrl_->RecordLoss();
115	  }
116	  if (invalid_lines > 0) {
117	    text_stream_.ClearInvalidLineCount();
118	  }
119	
120	  // 成功解析出有效包即证明链路活跃：读路径持续喂入成功率样本，
121	  // 否则无 cmd_vel 时 frames_total 恒为 0，链路质量永远停在 UNKNOWN。
122	  for (std::size_t i = 0; i < packets.size(); ++i) {
123	    backend_ctrl_->RecordSuccess(0.0);
124	  }
125	
126	  for (const auto& pkt : packets) {
127	    if (pkt.kind != amr_dispatcher_core::chassis::ChassisPacketKind::kOdometry) {
128	      continue;
129	    }
130	    const auto& o = pkt.odometry;
131	
132	    nav_msgs::msg::Odometry odom_msg;
133	    odom_msg.header.stamp = now;
134	    odom_msg.header.frame_id = odom_frame_id_;
135	    odom_msg.child_frame_id = base_frame_id_;
136	    odom_msg.pose.pose.position.x = o.x_m;
137	    odom_msg.pose.pose.position.y = o.y_m;
138	    odom_msg.pose.pose.position.z = 0.0;
139	
140	    tf2::Quaternion q;
141	    q.setRPY(0.0, 0.0, o.yaw_rad);
142	    odom_msg.pose.pose.orientation.x = q.x();
143	    odom_msg.pose.pose.orientation.y = q.y();
144	    odom_msg.pose.pose.orientation.z = q.z();
145	    odom_msg.pose.pose.orientation.w = q.w();
146	
147	    odom_msg.twist.twist.linear.x = o.linear_x_mps;
148	    odom_msg.twist.twist.angular.z = o.angular_z_radps;
149	
150	    odom_pub_->publish(odom_msg);
151	
152	    if (publish_tf_) {
153	      geometry_msgs::msg::TransformStamped tf;
154	      tf.header.stamp = now;
155	      tf.header.frame_id = odom_frame_id_;
156	      tf.child_frame_id = base_frame_id_;
157	      tf.transform.translation.x = o.x_m;
158	      tf.transform.translation.y = o.y_m;
159	      tf.transform.translation.z = 0.0;
160	      tf.transform.rotation = odom_msg.pose.pose.orientation;
161	      tf_broadcaster_->sendTransform(tf);
162	    }
163	  }
164	
165	  // 周期性评估降级与回切
166	  std::string reason;
167	  if (backend_ctrl_->EvaluateAndMaybeSwitch(&reason)) {
168	    RCLCPP_WARN(get_logger(), "Chassis backend switched: %s", reason.c_str());
169	  }
170	}
171	
172	void ChassisDriverNode::PublishHealth() {
173	  if (!backend_ctrl_) return;
174	  const auto snap = backend_ctrl_->quality().Snapshot();
175	  amr_dispatcher_interfaces::msg::ChassisLinkHealth msg;
176	  msg.header.stamp = this->now();
177	  msg.backend_name = backend_ctrl_->current() ? backend_ctrl_->current()->Name() : "none";
178	  msg.frames_total = snap.frames_total;
179	  msg.frames_success = snap.frames_success;
180	  msg.frames_lost = snap.frames_lost;
181	  msg.frames_crc_error = snap.frames_crc_error;
182	  msg.loss_rate = snap.loss_rate;
183	  msg.avg_latency_ms = snap.average_latency_ms;
184	  msg.max_latency_ms = snap.max_latency_ms;
185	  msg.is_healthy = backend_ctrl_->quality().IsHealthy();
186	
187	  switch (snap.tier) {
188	    case amr_dispatcher_core::chassis::LinkHealthTier::kHealthy:
189	      msg.tier = "HEALTHY";
190	      break;
191	    case amr_dispatcher_core::chassis::LinkHealthTier::kDegraded:
192	      msg.tier = "DEGRADED";
193	      break;
194	    case amr_dispatcher_core::chassis::LinkHealthTier::kCritical:
195	      msg.tier = "CRITICAL";
196	      break;
197	    case amr_dispatcher_core::chassis::LinkHealthTier::kUnknown:
198	    default:
199	      msg.tier = "UNKNOWN";
200	      break;
201	  }
202	  health_pub_->publish(msg);
203	
204	  if (heartbeat_pub_) {
205	    std_msgs::msg::Bool hb;
206	    hb.data = true;
207	    heartbeat_pub_->publish(hb);
208	  }
209	}
210	
211	}  // namespace amr_dispatcher_ros
212	
213	int main(int argc, char* argv[]) {
214	  rclcpp::init(argc, argv);
215	  auto node = std::make_shared<amr_dispatcher_ros::ChassisDriverNode>();
216	  rclcpp::spin(node);
217	  rclcpp::shutdown();
218	  return 0;
219	}
