1	#include "amr_dispatcher_ros/navigate_sequence_bridge_node.hpp"
2	
3	#include <cmath>
4	#include <chrono>
5	#include <utility>
6	
7	using namespace std::chrono_literals;
8	
9	namespace amr_dispatcher_ros {
10	
11	NavigateSequenceBridgeNode::NavigateSequenceBridgeNode(const rclcpp::NodeOptions& options)
12	    : rclcpp::Node("navigate_sequence_bridge_node", options) {
13	  declare_parameter("use_nav2", false);
14	  declare_parameter("nav2_action_name", "/navigate_to_pose");
15	  declare_parameter("plan_topic", "/plan");
16	
17	  use_nav2_ = get_parameter("use_nav2").as_bool();
18	  nav2_action_name_ = get_parameter("nav2_action_name").as_string();
19	  plan_topic_ = get_parameter("plan_topic").as_string();
20	
21	#ifdef AMR_HAVE_NAV2_MSGS
22	  nav2_compiled_ = true;
23	  nav2_client_ = rclcpp_action::create_client<nav2_msgs::action::NavigateToPose>(
24	      this, nav2_action_name_);
25	#else
26	  nav2_compiled_ = false;
27	#endif
28	  if (use_nav2_ && !nav2_compiled_) {
29	    // 镜像缺 nav2_msgs：use_nav2:=true 时打 FATAL 并降级 fallback，容器构建永不因 Nav2 挂掉
30	    RCLCPP_FATAL(get_logger(),
31	                 "use_nav2=true but nav2_msgs was not available at build time; "
32	                 "degrading to /plan fallback");
33	    use_nav2_ = false;
34	  }
35	
36	  action_server_ = rclcpp_action::create_server<NavigateSequence>(
37	      this, "/navigate_sequence",
38	      std::bind(&NavigateSequenceBridgeNode::HandleGoal, this, std::placeholders::_1,
39	                std::placeholders::_2),
40	      std::bind(&NavigateSequenceBridgeNode::HandleCancel, this, std::placeholders::_1),
41	      std::bind(&NavigateSequenceBridgeNode::HandleAccepted, this, std::placeholders::_1));
42	
43	  plan_pub_ = create_publisher<nav_msgs::msg::Path>(plan_topic_, 1);
44	  tracking_error_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
45	      "/tracking/error", 10,
46	      std::bind(&NavigateSequenceBridgeNode::TrackingErrorCb, this, std::placeholders::_1));
47	
48	  // cancel 终结轮询：HandleCancel 受理后需要等到 goal 进入 CANCELING 才能 canceled()
49	  cancel_poll_timer_ = create_wall_timer(
50	      100ms, std::bind(&NavigateSequenceBridgeNode::CancelPollTick, this));
51	
52	  RCLCPP_INFO(get_logger(), "NavigateSequence bridge up: backend=%s, plan_topic=%s",
53	              use_nav2_ ? "nav2" : "plan(fallback)", plan_topic_.c_str());
54	}
55	
56	rclcpp_action::GoalResponse NavigateSequenceBridgeNode::HandleGoal(
57	    const rclcpp_action::GoalUUID& /*uuid*/,
58	    std::shared_ptr<const NavigateSequence::Goal> goal) {
59	  if (!goal || goal->waypoints.empty()) {
60	    RCLCPP_WARN(get_logger(), "Rejecting NavigateSequence goal: waypoints empty");
61	    return rclcpp_action::GoalResponse::REJECT;
62	  }
63	  if (current_goal_ && current_goal_->is_active()) {
64	    RCLCPP_WARN(get_logger(),
65	                "Rejecting NavigateSequence goal: previous goal still active (single-vehicle model)");
66	    return rclcpp_action::GoalResponse::REJECT;
67	  }
68	  // DEFER + HandleAccepted 里显式 execute()：不受框架是否隐式 execute 影响的唯一稳妥路径
69	  return rclcpp_action::GoalResponse::ACCEPT_AND_DEFER;
70	}
71	
72	rclcpp_action::CancelResponse NavigateSequenceBridgeNode::HandleCancel(
73	    const std::shared_ptr<GoalHandleNavSeq> goal_handle) {
74	  if (goal_handle != current_goal_) {
75	    return rclcpp_action::CancelResponse::REJECT;
76	  }
77	  // 只受理取消请求：rclcpp_action 在本回调返回 ACCEPT 之后才把 goal 迁移到
78	  // CANCELING，而 canceled() 只允许在 CANCELING 态调用——终结交给 CancelPollTick。
79	  return rclcpp_action::CancelResponse::ACCEPT;
80	}
81	
82	void NavigateSequenceBridgeNode::HandleAccepted(
83	    const std::shared_ptr<GoalHandleNavSeq> goal_handle) {
84	  const auto goal = goal_handle->get_goal();
85	  // ACCEPTED -> EXECUTING：publish_feedback/succeed/abort 的前置条件
86	  goal_handle->execute();
87	
88	  current_goal_ = goal_handle;
89	  station_names_ = goal->station_names;
90	  loop_ = goal->loop;
91	  current_index_ = 0;
92	  completed_waypoints_ = 0;
93	  failed_waypoints_ = 0;
94	  waiting_arrival_ = false;
95	  nav2_pending_ = false;
96	
97	  // 预计算航点位姿：frame_id=map，orientation 由相邻点 atan2 得 yaw（单点 yaw=0）
98	  nav_poses_.clear();
99	  const auto& wps = goal->waypoints;
100	  const std::size_t n = wps.size();
101	  nav_poses_.reserve(n);
102	  for (std::size_t i = 0; i < n; ++i) {
103	    double yaw = 0.0;
104	    if (n > 1) {
105	      const geometry_msgs::msg::PoseStamped& a = (i + 1 < n) ? wps[i] : wps[i - 1];
106	      const geometry_msgs::msg::PoseStamped& b = (i + 1 < n) ? wps[i + 1] : wps[i];
107	      yaw = std::atan2(b.pose.position.y - a.pose.position.y,
108	                       b.pose.position.x - a.pose.position.x);
109	    }
110	    geometry_msgs::msg::PoseStamped ps;
111	    ps.header.frame_id = "map";
112	    ps.pose = wps[i].pose;
113	    ps.pose.orientation.z = std::sin(yaw / 2.0);
114	    ps.pose.orientation.w = std::cos(yaw / 2.0);
115	    nav_poses_.push_back(ps);
116	  }
117	
118	  RCLCPP_INFO(get_logger(), "NavigateSequence goal accepted: %zu waypoint(s), loop=%d, backend=%s",
