255	    return;
256	  }
257	  if (!nav2_client_ || !nav2_client_->action_server_is_ready()) {
258	    // 单点失败 -> 整 goal abort
259	    failed_waypoints_++;
260	    auto result = std::make_shared<NavigateSequence::Result>();
261	    result->success = false;
262	    result->message = "nav2 action server not available: " + nav2_action_name_;
263	    result->completed_waypoints = completed_waypoints_;
264	    result->failed_waypoints = failed_waypoints_;
265	    RCLCPP_ERROR(get_logger(), "%s (waypoint %zu/%zu)", result->message.c_str(),
266	                 current_index_ + 1, nav_poses_.size());
267	    StopFallbackMotion();  // 终结路径统一停车（use_nav2_ 下为空操作）
268	    current_goal_->abort(result);
269	    current_goal_.reset();
270	    waiting_arrival_ = false;
271	    nav2_pending_ = false;
272	    return;
273	  }
