275	  nav2_msgs::action::NavigateToPose::Goal nav_goal;
276	  nav_goal.pose = nav_poses_[current_index_];
277	  nav_goal.pose.header.stamp = now();
278	  nav2_pending_ = true;
279	  const std::weak_ptr<GoalHandleNavSeq> seq_goal = current_goal_;
280	
281	  rclcpp_action::Client<nav2_msgs::action::NavigateToPose>::SendGoalOptions opts;
282	  opts.feedback_callback =
283	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& gh,
284	                       const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb) {
285	        Nav2FeedbackCb(gh, fb, seq_goal);
286	      };
287	  opts.result_callback =
288	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::WrappedResult& result) {
289	        Nav2ResultCb(result, seq_goal);
290	      };
291	  nav2_client_->async_send_goal(nav_goal, opts);
292	  PublishSeqFeedback("NAVIGATING", 0.0);
