297	void NavigateSequenceBridgeNode::Nav2FeedbackCb(
298	    const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& /*gh*/,
299	    const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb,
300	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
301	  // 身份校验：只处理仍属于当前 NavigateSequence goal 的在途反馈
302	  const auto locked = seq_goal.lock();
303	  if (!locked || locked != current_goal_ || !nav2_pending_) {
304	    return;
305	  }
306	  PublishSeqFeedback("NAVIGATING", fb ? static_cast<double>(fb->feedback.distance_remaining) : 0.0);
