309	void NavigateSequenceBridgeNode::Nav2ResultCb(
310	    const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::WrappedResult& result,
311	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
312	  const auto locked = seq_goal.lock();
313	  if (!locked || locked != current_goal_ || !nav2_pending_) {
314	    return;  // 已被 cancel 终结 / 已换 goal：丢弃过期结果
315	  }
316	  nav2_pending_ = false;
317	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
318	      result.result->success) {
319	    PublishSeqFeedback("AT_STATION", 0.0);
320	    AdvanceAfterArrival();
321	    return;
322	  }
323	  // 单点失败 -> 整 goal abort
324	  failed_waypoints_++;
325	  auto res = std::make_shared<NavigateSequence::Result>();
326	  res->success = false;
327	  res->message = "navigate_to_pose failed at waypoint " + std::to_string(current_index_ + 1);
328	  res->completed_waypoints = completed_waypoints_;
329	  res->failed_waypoints = failed_waypoints_;
330	  RCLCPP_ERROR(get_logger(), "%s (code=%d)", res->message.c_str(),
331	               static_cast<int>(result.code));
332	  StopFallbackMotion();  // 终结路径统一停车（use_nav2_ 下为空操作）
333	  current_goal_->abort(res);
334	  current_goal_.reset();
335	  waiting_arrival_ = false;
336	}
337	#endif  // AMR_HAVE_NAV2_MSGS
