65	        std::chrono::milliseconds(period_ms),
66	        std::bind(&LifecycleCoordinatorNode::CoordinatorTick, this));
67	
68	    RCLCPP_INFO(get_logger(), "Lifecycle Coordinator & Readiness Probe initialized (auto_bringup=%s)",
69	                auto_bringup_ ? "true" : "false");
70	  }
