72	 private:
73	  void CoordinatorTick() {
74	    if (!dispatcher_get_state_cli_->service_is_ready()) {
75	      return;
76	    }
77	
78	    // 1. 获取 dispatcher_node 当前生命周期状态。
79	    //    单线程 executor 下 spin 期间不能嵌套 wait_for future（会永久阻塞），
80	    //    必须异步发送 + 轮询 shared_future 的就绪位。
