90	        pending_get_state_ = {};
91	        get_state_wait_ticks_ = 0;
92	      }
93	      return;
94	    }
95	    current_dispatcher_state_ = pending_get_state_.get()->current_state.label;
96	    pending_get_state_ = {};
97	    get_state_wait_ticks_ = 0;
98	
99	    // 2. 自动级联提拉状态机: unconfigured -> inactive -> active
100	    if (auto_bringup_) {
101	      if (current_dispatcher_state_ == "unconfigured") {
102	        RCLCPP_INFO(get_logger(), "Promoting dispatcher_node: unconfigured -> configure()");
