116	  void SendTransition(uint8_t transition_id) {
117	    if (!dispatcher_change_state_cli_->service_is_ready()) return;
118	    auto req = std::make_shared<lifecycle_msgs::srv::ChangeState::Request>();
119	    req->transition.id = transition_id;
120	    dispatcher_change_state_cli_->async_send_request(req);
121	  }
