namespace amr_dispatcher_ros {

/**
 * @brief 工业级多组件生命周期协调器与就绪探针 (Lifecycle Coordinator & Readiness Probe)
 * 实施严格的拓扑依赖启动与停止链：
 * ChassisDriver (Active) -> SafetyGate (Ready) -> PathTracker (Ready) -> DispatcherNode (Active)
 * 向上暴露统一的 `/system/ready` 与 `/system/healthy` 服务，供上层 WMS/REST 网关拦截派单。
 */
class LifecycleCoordinatorNode : public rclcpp::Node {
 public:
  explicit LifecycleCoordinatorNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : rclcpp::Node("lifecycle_coordinator_node", options) {
    declare_parameter("auto_bringup", true);
    declare_parameter("check_period_ms", 500);

    auto_bringup_ = get_parameter("auto_bringup").as_bool();
    int period_ms = get_parameter("check_period_ms").as_int();

    dispatcher_get_state_cli_ =
        create_client<lifecycle_msgs::srv::GetState>("/dispatcher_node/get_state");
    dispatcher_change_state_cli_ =
        create_client<lifecycle_msgs::srv::ChangeState>("/dispatcher_node/change_state");

  const std::size_t n = wps.size();
  nav_poses_.reserve(n);
  for (std::size_t i = 0; i < n; ++i) {
    double yaw = 0.0;
    if (n > 1) {
      const geometry_msgs::msg::PoseStamped& a = (i + 1 < n) ? wps[i] : wps[i - 1];
      const geometry_msgs::msg::PoseStamped& b = (i + 1 < n) ? wps[i + 1] : wps[i];
      yaw = std::atan2(b.pose.position.y - a.pose.position.y,
                       b.pose.position.x - a.pose.position.x);
    }
    geometry_msgs::msg::PoseStamped ps;
    ps.header.frame_id = "map";
    ps.pose = wps[i].pose;
    ps.pose.orientation.z = std::sin(yaw / 2.0);
    ps.pose.orientation.w = std::cos(yaw / 2.0);
    nav_poses_.push_back(ps);
  }

  RCLCPP_INFO(get_logger(), "NavigateSequence goal accepted: %zu waypoint(s), loop=%d, backend=%s",
    if (!nav_client_) {
      FailMission(m.id, "navigate_sequence client not configured");
      return;
    }
    if (!nav_client_->action_server_is_ready()) {
      FailMission(m.id, "navigate_sequence action server not available (is bridge running?)");
      return;
    }
    const auto& wp = waypoints.back();
    NavigateSequence::Goal nav_goal;
    geometry_msgs::msg::PoseStamped ps;
    ps.header.stamp = now();
    ps.header.frame_id = "map";
    ps.pose.position.x = wp.x;
    ps.pose.position.y = wp.y;
    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
    nav_goal.waypoints.push_back(ps);
    nav_goal.station_names.push_back(m.dropoff_station);
    nav_goal.loop = false;

